491: func sanitize(value string) string {
492: 	value = strings.ReplaceAll(value, "/", "-")
493: 	value = strings.ReplaceAll(value, ".", "-")
494: 	value = strings.ReplaceAll(value, " ", "-")
495: 	return value
496: }
