package main

import "testing"

func TestAdd(t *testing.T) {
	if add(2, 3) != 5 {
		t.Fatalf("add(2, 3) = %d, want 5", add(2, 3))
	}
}

func TestIndexOf(t *testing.T) {
	tests := []struct {
		name  string
		slice []int
		value int
		want  int
	}{
		{name: "first element", slice: []int{4, 7, 9}, value: 4, want: 0},
		{name: "middle element", slice: []int{4, 7, 9}, value: 7, want: 1},
		{name: "last element", slice: []int{4, 7, 9}, value: 9, want: 2},
		{name: "missing value", slice: []int{4, 7, 9}, value: 5, want: -1},
		{name: "empty slice", slice: []int{}, value: 5, want: -1},
		{name: "duplicate value returns first", slice: []int{3, 3, 8}, value: 3, want: 0},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if got := indexOf(tt.slice, tt.value); got != tt.want {
				t.Fatalf("indexOf(%v, %d) = %d, want %d", tt.slice, tt.value, got, tt.want)
			}
		})
	}
}

func TestIndexOfStrings(t *testing.T) {
	words := []string{"go", "test", "bench"}
	if got := indexOf(words, "test"); got != 1 {
		t.Fatalf("indexOf(%v, test) = %d, want 1", words, got)
	}
	if got := indexOf(words, "missing"); got != -1 {
		t.Fatalf("indexOf(%v, missing) = %d, want -1", words, got)
	}
}

